param([int]$Port=51731,[string]$Root=(Split-Path -Parent $PSScriptRoot))
$L=New-Object System.Net.HttpListener;$L.Prefixes.Add("http://127.0.0.1:$Port/");$L.Start();try{while($L.IsListening){$c=$L.GetContext();$r=$c.Request.Url.AbsolutePath.TrimStart('/');if(!$r){$r='index.html'};$f=[IO.Path]::GetFullPath((Join-Path $Root $r));if(!(Test-Path $f -PathType Leaf)){$c.Response.StatusCode=404;$c.Response.Close();continue};$e=[IO.Path]::GetExtension($f);$m=@{'.html'='text/html';'.js'='text/javascript';'.css'='text/css';'.webp'='image/webp';'.wav'='audio/wav'};if($m[$e]){$c.Response.ContentType=$m[$e]};$b=[IO.File]::ReadAllBytes($f);$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}}finally{$L.Stop()}